// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { float64ndarray } from '@stdlib/types/ndarray';

/**
* Performs the symmetric rank 1 operation `A = alpha*x*x^T + A` for a symmetric matrix supplied in packed form `A`, where `alpha` is a scalar, `x` is an ndarray, and `A` is an `N` by `N` matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional symmetric input ndarray.
*     -   first zero-dimensional ndarray containing a scalar constant.
*
* @param arrays - array-like object containing ndarrays
* @returns output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float64',  new Float64Array( [ 1.0, 2.0, 3.0, 1.0, 2.0, 1.0 ] ), [ 6 ], [ 1 ], 0, 'row-major' );
*
* var alpha = scalar2ndarray( 1.0, {
*     'dtype': 'float64'
* });
*
* var out = dspr( [ x, A, alpha ] );
* // returns <ndarray>[ 2.0, 4.0, 6.0, 5.0, 8.0, 10.0 ]
*
* var bool = ( out === A );
* // returns true
*/
declare function dspr( arrays: [ float64ndarray, float64ndarray, float64ndarray ] ): float64ndarray;


// EXPORTS //

export = dspr;
